const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cuttack = ee.Geometry.Point([85.8793, 20.4659]);
  const buffer = cuttack.buffer(5000); // 5km buffer for regional average

  const date1 = '2019-04-30';
  const date2 = '2019-05-04';

  // 2. Data Acquisition - Using VIIRS DNB monthly composites for better data quality
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filterBounds(cuttack);

  // Get April 2019 composite (includes April 30)
  const april2019 = viirs.filterDate('2019-04-01', '2019-05-01').first();
  // Get May 2019 composite (includes May 4)
  const may2019 = viirs.filterDate('2019-05-01', '2019-06-01').first();

  // Check if images exist
  const aprilExists = april2019 ? true : false;
  const mayExists = may2019 ? true : false;

  if (!aprilExists || !mayExists) {
    console.log(`April 2019 image: ${aprilExists ? 'Found' : 'Missing'}`);
    console.log(`May 2019 image: ${mayExists ? 'Found' : 'Missing'}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean brightness
  const aprilBrightness = april2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const mayBrightness = may2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  // Check for valid pixels
  const aprilCount = april2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const mayCount = may2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log(`April 30 brightness: ${aprilBrightness ? aprilBrightness.toFixed(4) : 'None'}`);
  console.log(`May 4 brightness: ${mayBrightness ? mayBrightness.toFixed(4) : 'None'}`);
  console.log(`April valid pixels: ${aprilCount}`);
  console.log(`May valid pixels: ${mayCount}`);

  // 4. Validation & Final Answer
  if (aprilBrightness === null || mayBrightness === null || 
      isNaN(aprilBrightness) || isNaN(mayBrightness)) {
    console.log("<answer>C3</answer>");
  } else if (aprilCount === 0 || mayCount === 0) {
    console.log("<answer>C2</answer>");
  } else if (mayBrightness < aprilBrightness) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
